KG42.register("edges-a82a9b613db682fd755c293b",{"id":"S-ff6c33e3f58ddff9","source":"COMP-334f35169e6933ed","type":"links","target":"COMP-b646a091517c6af0","evidence_class":"S","scientific_acceptance":false,"relation_scope":"original_occurrence_pair_only","internal_to_parent":false,"paper_ids":["15-multiagent_reverse_auction"],"assertions":[{"id":"15-multiagent_reverse_auction::v141-c-R005::E::v141-c-R005-E001","paper":"15-multiagent_reverse_auction","rule_id":"v141-c-R005","rule_ref":"15-multiagent_reverse_auction::v141-c-R005","record":{"edge_id":"v141-c-R005-E001","source":"bidding.supply","target":"coordination.local_operator","type":"links","constraint_ids":["v141-c-R005-C001"],"evidence_ids":["v141-b-g01-E15","v141-b-g01-E16"]},"evidence_class":"S","provenance_gate":"direct_C_edge_with_constraint_and_source_excerpt","scientific_acceptance":false,"accepted_constraint_ids":["v141-c-R005-C001"],"held_constraint_ids":[],"semantic_review_status":"supported","source":"COMP-334f35169e6933ed","target":"COMP-b646a091517c6af0","source_occurrence_id":"15-multiagent_reverse_auction::v141-c-R005::V::bidding.supply","target_occurrence_id":"15-multiagent_reverse_auction::v141-c-R005::V::coordination.local_operator","source_unit_id":"15-multiagent_reverse_auction::v141-a-M01::bidding.supply","target_unit_id":"15-multiagent_reverse_auction::v141-a-M01::coordination.local_operator","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"coordination","context_text":"Next-hour DER bids in the hour-ahead reverse auction for the grid-connected microgrid's lumped load. | Procurement for the lumped load through the hour-ahead reverse auction in the studied grid-connected microgrid.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E15","v141-b-g01-E16"]},"active":true,"source_signature":"fd382c3caf6990567beb1c253f270ca4b8d8b74eb5625b00295c2d86f8d94b05","relation_scope":"original_occurrence_pair_only","internal_to_parent":false,"source_science":{"mechanism_id":"v141-a-M01","source_definition":"Supply-bidding participation requires yellow-pages registration, which implements admission to this microgrid auction. Scope: Supply bidding by available generators in the microgrid's hour-ahead reverse auction. Condition: An available microgrid generator seeks to participate in bidding. The DER aggregator coordinates supply submission by soliciting bids from registered agents. Scope: Solicitation of next-hour DER supply bids in the microgrid reverse auction. Condition: Agents are registered in the yellow pages. The lowered auction-price signal coordinates renewed supply submissions: bidders that remain interested submit the new price, while others withdraw for that hour. Scope: Renewed supply bidding within a particular hourly microgrid auction. Condition: Submitted supply is higher than demand. The bidder submits a supply bid. Scope: Initial bid solicitation for available, registered microgrid generators in Algorithm 1. Condition: DER base price \u003c utility base price. Supply submission is withheld: the bidder drops and does not participate. Scope: Initial bid solicitation for available, registered microgrid generators in Algorithm 1. Condition: The DER base price is not less than the utility base price.","target_definition":"DER supply submissions declaring available power and the next-hour price are sent to and collected by the DER aggregator. Scope: Next-hour DER bids in the hour-ahead reverse auction for the grid-connected microgrid's lumped load. The aggregator's procurement objective is to purchase the required amount of energy with the least cost. Scope: Procurement for the lumped load through the hour-ahead reverse auction in the studied grid-connected microgrid.","constraints":[{"constraint_id":"v141-c-R005-C001","kind":"procedural","role":"core","statement":"DER supply submissions declaring available power and the next-hour price are sent to and collected by the DER aggregator. Scope: Next-hour DER bids in the hour-ahead reverse auction for the grid-connected microgrid's lumped load.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["bidding.supply","coordination.local_operator"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-E15","v141-b-g01-E16"]}],"evidence":[{"evidence_id":"v141-b-g01-E15","location":{"location_id":"src-1b3df4bc99-p04-c2r3__v141-a-M01-coordination","page":4,"printed_page":null,"section":"IV. Proposed Methodology","anchor_text":"The aggregator manages the communication and the infor- his mation exchange between participants to ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"The aggregator manages the communication and the information exchange between participants to minimize the cost of the electricity to be purchased for the lumped load. The aggregator agent is the main entity operating the auction process. Its task is to solicit bids form the agents registered to the yellow pages, and to invite them to participate in the auction. The ultimate goal is to purchase the required amount of power with the lowest cost. DERs submit bids to the DER aggregator, declaring the power available to sell and the price for the next hour. Each DER has a generation capacity, marginal cost, and availability."},{"evidence_id":"v141-b-g01-E16","location":{"location_id":"src-1b3df4bc99-p04-c2r4__v141-a-M01-participation","page":4,"printed_page":null,"section":"IV. Proposed Methodology","anchor_text":"terminated. All available generators in the microgrid should 1) register to the yellow pages in orde","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"condition"},"source_text":"A reverse auction model has been implemented and realistically operated. Algorithm 1 briefly expresses the simplified pseudo code of the proposed reverse auction model. In Algorithm 1, the process is continuous unless the program is terminated. All available generators in the microgrid should register to the yellow pages in order to participate in bidding processes. The required amount of load is assumed to be correctly estimated for each upcoming hour; therefore the aggregator agent has this information ready to inform all agents registered to the yellow page. The main purpose of the aggregator agent is to purchase the required amount of energy with the least cost. The aggregator agent collects the submitted bids and checks whether the submitted supply matches the demand."}],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"coordination","context_text":"Next-hour DER bids in the hour-ahead reverse auction for the grid-connected microgrid's lumped load. | Procurement for the lumped load through the hour-ahead reverse auction in the studied grid-connected microgrid.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E15","v141-b-g01-E16"]},"source_record":{"edge_id":"v141-c-R005-E001","source":"bidding.supply","target":"coordination.local_operator","type":"links","constraint_ids":["v141-c-R005-C001"],"evidence_ids":["v141-b-g01-E15","v141-b-g01-E16"]},"paper_scope_note":"Registration, auction invitation, bid, eligibility, and final power command are checked separately; the utility base price differs from the DER private base price; the general single-winner and two-winner cases are not combined into the same condition."}}],"assertion_ids":["15-multiagent_reverse_auction::v141-c-R005::E::v141-c-R005-E001"]});
